#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdlib.h>

// Mock exit function to capture exit calls
static int exit_called = 0;
static int exit_status = 0;

void mock_exit(int status) {
    exit_called = 1;
    exit_status = status;
}

// Function pointer for original exit
void (*original_exit)(int) = exit;

void setUp(void) {
    exit_called = 0;
    exit_status = 0;
    // Redirect exit to mock
    exit = mock_exit;
}

void tearDown(void) {
    // Restore original exit
    exit = original_exit;
}

void unit_test_push_stack_overflow(void) {
    // Setup: Fill the stack to capacity (st.top == 9)
    // The stack size is 10 (indices 0-9), so we need to push 10 items
    // Start with empty stack (st.top = -1 after initStack)
    initStack();

    // Push 10 characters to fill the stack completely
    // After 10 pushes, st.top will be 9 (0-based index)
    push('a');
    push('b');
    push('c');
    push('d');
    push('e');
    push('f');
    push('g');
    push('h');
    push('i');
    push('j');

    // Verify stack is full before the test
    TEST_ASSERT_EQUAL_INT(1, isFull());
    TEST_ASSERT_EQUAL_INT(9, getStackSize() - 1); // getStackSize returns st.top + 1

    // Reset exit capture
    exit_called = 0;
    exit_status = 0;

    // Test: Attempt to push one more character when stack is full
    // This should trigger the overflow path: printf("Stack overflow...") and exit(1)
    push('k');

    // Verify exit was called with status 1
    TEST_ASSERT_EQUAL_INT(1, exit_called);
    TEST_ASSERT_EQUAL_INT(1, exit_status);

    // Note: The printf("Stack overflow...") will still execute but won't affect test
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_push_stack_overflow);
    return UNITY_END();
}

